<?php
declare(strict_types=1);
namespace CommunityHub;
final class LearningReminders {
 const DEFAULTS=['enabled'=>true,'training_interval_days'=>7,'certification_days'=>[30,7,1]];
 const TRAINING="SELECT e.id source_id,e.user_id,e.course_id,c.title,TIMESTAMPDIFF(DAY,e.enrolled_at,NOW()) age_days FROM lms_enrollments e JOIN lms_courses c ON c.id=e.course_id JOIN users u ON u.id=e.user_id WHERE u.is_active=1 AND c.status='published' AND e.status IN ('enrolled','in_progress','failed')";
 const CERTS="SELECT uc.id source_id,uc.user_id,c.name title,DATE_FORMAT(uc.expires_at,'%Y-%m-%d %H:%i:%s') expiry_key,DATEDIFF(DATE(uc.expires_at),CURRENT_DATE()) days_left,(uc.expires_at<=NOW()) expired FROM user_certifications uc JOIN certifications c ON c.id=uc.certification_id JOIN users u ON u.id=uc.user_id WHERE u.is_active=1 AND uc.expires_at IS NOT NULL";
 public static function validate(array $d):array{$interval=$d['training_interval_days']??null;$days=$d['certification_days']??[];if(!is_array($days))$days=array_map('trim',explode(',',(string)$days));if(!is_numeric($interval)||(float)$interval!==(float)(int)$interval||(int)$interval<1||(int)$interval>365||!$days||count($days)>6)throw new HttpError('Use a training interval of 1–365 days and up to six certification thresholds of 1–365 days.');foreach($days as $v)if(!is_numeric($v)||(float)$v!==(float)(int)$v||(int)$v<1||(int)$v>365)throw new HttpError('Certification thresholds must be whole days from 1–365.');$days=array_values(array_unique(array_map('intval',$days)));rsort($days);return ['enabled'=>in_array($d['enabled']??false,[true,'1','on'],true),'training_interval_days'=>(int)$interval,'certification_days'=>$days];}
 public static function settings():array{$r=App::row("SELECT setting_value FROM site_settings WHERE setting_key='lms_reminder_settings'");return $r?self::validate(json_decode($r['setting_value'],true,512,JSON_THROW_ON_ERROR)):self::DEFAULTS;}
 public static function reminder(string $kind,array $r,array $c):?array{if($kind==='training'){$cycle=(int)floor((int)$r['age_days']/$c['training_interval_days']);if($cycle<1)return null;return ['period'=>$c['training_interval_days'].':'.$cycle,'title'=>'Training reminder','message'=>'Your '.$r['title'].' training is unfinished. Review your next steps.','url'=>'/lms/courses/'.$r['course_id']];}$stage=!empty($r['expired'])?'expired':null;if(!$stage){$eligible=array_filter($c['certification_days'],fn($d)=>(int)$r['days_left']<=$d);if(!$eligible)return null;$stage=(string)min($eligible);}return ['period'=>$r['expiry_key'].'|'.$stage,'title'=>$stage==='expired'?'Certification expired':'Certification renewal reminder','message'=>$r['title'].($stage==='expired'?' has expired. Contact training staff to arrange renewal.':' expires on '.substr($r['expiry_key'],0,10).'. Arrange renewal with training staff.'),'url'=>'/lms'];}
 public static function run():array{$config=self::settings();if(!$config['enabled'])return ['disabled'=>true,'sent'=>0];$sent=0;foreach(['training'=>self::TRAINING,'certification'=>self::CERTS] as $kind=>$sql)foreach(App::rows($sql) as $candidate){if(!self::reminder($kind,$candidate,$config))continue;$sent+=(int)App::transaction(function()use($kind,$sql,$candidate,$config){$row=App::row($sql.($kind==='training'?' AND e.id=?':' AND uc.id=?').' FOR UPDATE',[$candidate['source_id']]);$item=$row?self::reminder($kind,$row,$config):null;if(!$item)return false;$key=hash('sha256',implode('|',[$kind,$row['user_id'],$row['source_id'],$item['period']]));$claim=App::query('INSERT IGNORE INTO lms_reminder_deliveries(reminder_key,user_id,kind,source_id,period_key) VALUES(?,?,?,?,?)',[$key,$row['user_id'],$kind,$row['source_id'],$item['period']]);if(!$claim->rowCount())return false;App::query('INSERT INTO notifications(user_id,title,message,url) VALUES(?,?,?,?)',[$row['user_id'],$item['title'],$item['message'],$item['url']]);return true;});}return ['ok'=>true,'sent'=>$sent];}
 public static function web(string $method,string $path,array $d):void{$u=Auth::requireUser(true,Domain::ADMINS);$current=App::row('SELECT role,is_active FROM users WHERE id=?',[$u['id']]);if(empty($current['is_active']))throw new HttpError('Active administrator required.',403);Domain::role($current,Domain::ADMINS);if($method==='POST'){if($path==='/lms/admin/reminders/run'){$r=self::run();$_SESSION['reminderResult']=!empty($r['disabled'])?'Reminders are disabled.':$r['sent'].' reminders delivered.';}elseif($path==='/lms/admin/reminders'){$config=self::validate($d);App::query("INSERT INTO site_settings(setting_key,setting_value) VALUES('lms_reminder_settings',?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)",[json_encode($config,JSON_THROW_ON_ERROR)]);$_SESSION['reminderResult']='Reminder settings saved.';}else throw new HttpError('Page not found.',404);App::redirect('/lms/admin/reminders');}if($path!=='/lms/admin/reminders')throw new HttpError('Page not found.',404);$config=self::settings();View::layout('Training reminders',function()use($config){View::heading('Training reminders','Deliver reminders to the shared website and phone inbox.');if(isset($_SESSION['reminderResult'])){?><p role="status"><?=escape($_SESSION['reminderResult'])?></p><?php unset($_SESSION['reminderResult']);}?><section class="panel"><h2>Reminder timing</h2><?php View::form('/lms/admin/reminders',['enabled'=>['label'=>'Enable reminders','type'=>'checkbox'],'training_interval_days'=>['label'=>'Unfinished training interval (days)','type'=>'number','required'=>true],'certification_days'=>['label'=>'Certification reminder days before expiry (comma-separated)','required'=>true]],'Save settings',[...$config,'certification_days'=>implode(', ',$config['certification_days'])]);?><p>Completed and unpublished courses, inactive accounts and certifications without expiry dates are excluded. Expired certifications receive one notice. Configure the existing PHP cron job to check every 15 minutes.</p><?php View::form('/lms/admin/reminders/run',[],'Check now');?><h3>Recent deliveries</h3><?php View::table(App::rows('SELECT r.kind,r.sent_at,u.display_name FROM lms_reminder_deliveries r JOIN users u ON u.id=r.user_id ORDER BY r.sent_at DESC LIMIT 25'),['display_name'=>'Member','kind'=>'Reminder','sent_at'=>'Sent']);?></section><?php });}
}
